const template=document.createElement("template");template.innerHTML='\n  <style>\n    .ps-button {\n      height: 20px;\n      background: linear-gradient(to top, #e6e9f0 0%, #dadada 100%);\n      color: #3d3d3d;\n      border: 1px solid #c4c1c1;\n      font-size: 11px;\n      border-radius: 2px;\n      padding: 0 8px;\n      position: relative;\n      display: inline-flex;\n      align-items: center; /* Garantir que o texto seja alinhado verticalmente */\n      justify-content: center;\n      box-sizing: border-box;\n    }\n\n    .button-text {\n      line-height: 20px;\n      display: inline-block;\n      text-align: center;\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n      max-width: 100%;\n    }\n\n    .ps-button:hover {\n      background: #d4d6d6;\n      color: rgb(56, 56, 56);\n    }\n\n    .ps-button:active {\n      height: 19px;\n      background: #d4d6d6;\n      color: rgb(56, 56, 56);\n      transform: translate(0px, 1px);\n      border-top: 3px solid #5f5e5e;\n    }\n\n    /* Dark mode */\n    @media (prefers-color-scheme: dark), (prefers-color-scheme: darkest) {\n      .ps-button {\n        background-image: linear-gradient(to bottom, #919191 1%, #919191 5%, #6f6f6f 5%, #676767 44%, #5d5d5d 100%);\n        color: #E0E0E0;\n        border: 1px solid #232323;\n        box-shadow: 0px 1px 0px 1px rgb(95, 95, 95);\n      }\n      .ps-button:hover {\n        background: #aca8a8;\n        color: rgb(0, 0, 0);\n      }\n      .ps-button:active {\n        background: #686767;\n        color: rgb(0, 0, 0);\n        border-top: 3px solid #302f2f;\n      }\n    }\n\n    .desabilitar {\n      pointer-events: none;\n      color: #a0a0a0 !important;\n      background-image: none !important;\n      background-color: var(--uxp-host-background-color);\n      border: 1px solid var(--uxp-host-border-color);\n    }\n\n    @media (prefers-color-scheme: dark), (prefers-color-scheme: darkest) {\n      .desabilitar {\n        pointer-events: none;\n        color: #a0a0a0 !important;\n        background-image: none !important;\n        background-color: var(--uxp-host-background-color);\n        border: 1px solid var(--uxp-host-border-color);\n      }\n    }\n  </style>\n  <div class="ps-button">\n    <span class="button-text"></span>\n  </div>\n';class Botao extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.shadowRoot.appendChild(template.content.cloneNode(!0)),this.shadowRoot.querySelector(".button-text").textContent=this.getAttribute("texto");const t=this.shadowRoot.querySelector(".ps-button");t.style.width=this.getAttribute("size"),this.hasAttribute("disabled")&&(t.classList.add("desabilitar"),t.disabled=!0),t.addEventListener("click",(e=>{t.disabled&&(e.stopPropagation(),e.preventDefault())}))}static get observedAttributes(){return["disabled"]}attributeChangedCallback(t,e,n){const o=this.shadowRoot.querySelector(".ps-button");"disabled"===t&&(null!==n?(o.classList.add("desabilitar"),o.disabled=!0):(o.classList.remove("desabilitar"),o.disabled=!1))}disable(){this.setAttribute("disabled","")}enable(){this.removeAttribute("disabled")}}window.customElements.define("ps-button",Botao);